1	-- 渔业捕捞配额与渔捞日志核销：H2 内存库（MODE=MySQL）建表脚本，仅合成数据。
2	-- 所有重量单位千克（DECIMAL(14,3)），时刻为 UTC 时间线（TIMESTAMP），日期为 UTC 日界（DATE）。
3	-- 中文 COMMENT 使用 H2 的 COMMENT ON 语法（MySQL 兼容模式下不支持列级内联 COMMENT）。
4	
5	-- 渔船台账（合成）
6	CREATE TABLE IF NOT EXISTS vessel (
7	    code        VARCHAR(32)  NOT NULL PRIMARY KEY,
8	    name        VARCHAR(64)  NOT NULL,
9	    created_at  TIMESTAMP(6) NOT NULL
10	);
11	COMMENT ON TABLE vessel IS '渔船台账（合成数据）';
12	COMMENT ON COLUMN vessel.code IS '渔船编号';
13	COMMENT ON COLUMN vessel.name IS '渔船名称';
14	COMMENT ON COLUMN vessel.created_at IS '建档时刻（UTC）';
15	
16	-- 鱼种台账（合成），protected_species=TRUE 表示兼捕保护鱼种
17	CREATE TABLE IF NOT EXISTS species (
18	    code               VARCHAR(32)  NOT NULL PRIMARY KEY,
19	    name               VARCHAR(64)  NOT NULL,
20	    protected_species  BOOLEAN      NOT NULL
21	);
22	COMMENT ON TABLE species IS '鱼种台账（合成数据）';
23	COMMENT ON COLUMN species.code IS '鱼种编号';
24	COMMENT ON COLUMN species.name IS '鱼种名称';
25	COMMENT ON COLUMN species.protected_species IS '是否兼捕保护鱼种：TRUE 是，FALSE 否';
26	
27	-- 年度配额台账：船＋鱼种＋UTC 年度；used_kg 为已结案核销扣减重量（千克）
28	CREATE TABLE IF NOT EXISTS quota (
29	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
30	    vessel_code  VARCHAR(32)   NOT NULL,
31	    species_code VARCHAR(32)   NOT NULL,
32	    quota_year   INT           NOT NULL,
33	    quota_kg     DECIMAL(14,3) NOT NULL,
34	    used_kg      DECIMAL(14,3) NOT NULL DEFAULT 0,
35	    version      INT           NOT NULL DEFAULT 0,
36	    CONSTRAINT uq_quota_vessel_species_year UNIQUE (vessel_code, species_code, quota_year)
37	);
38	COMMENT ON TABLE quota IS '年度配额台账：船＋鱼种＋UTC 年度';
39	COMMENT ON COLUMN quota.vessel_code IS '渔船编号';
40	COMMENT ON COLUMN quota.species_code IS '鱼种编号';
41	COMMENT ON COLUMN quota.quota_year IS '配额年度（UTC）';
42	COMMENT ON COLUMN quota.quota_kg IS '年度核定配额（千克）';
43	COMMENT ON COLUMN quota.used_kg IS '已核销扣减重量（千克）';
44	COMMENT ON COLUMN quota.version IS '乐观锁版本号';
45	
46	-- 航次台账：DEPARTED→(IN_REVIEW)→DISCHARGED→CLOSED；frozen=TRUE 表示该船复核期间余额冻结
47	CREATE TABLE IF NOT EXISTS trip (
48	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
49	    trip_code   VARCHAR(48)  NOT NULL,
50	    vessel_code VARCHAR(32)  NOT NULL,
51	    depart_at   TIMESTAMP(6) NOT NULL,
52	    landed_at   TIMESTAMP(6) NULL,
53	    status      VARCHAR(16)  NOT NULL,
54	    frozen      BOOLEAN      NOT NULL DEFAULT FALSE,
55	    created_at  TIMESTAMP(6) NOT NULL,
56	    updated_at  TIMESTAMP(6) NOT NULL,
57	    CONSTRAINT uq_trip_code UNIQUE (trip_code)
58	);
59	CREATE INDEX IF NOT EXISTS idx_trip_vessel_status ON trip (vessel_code, status);
60	COMMENT ON TABLE trip IS '航次台账';
61	COMMENT ON COLUMN trip.trip_code IS '航次业务编号';
62	COMMENT ON COLUMN trip.vessel_code IS '渔船编号';
63	COMMENT ON COLUMN trip.depart_at IS '出港时刻（UTC）';
64	COMMENT ON COLUMN trip.landed_at IS '进港时刻（UTC），未进港为空';
65	COMMENT ON COLUMN trip.status IS '航次状态：DEPARTED/DISCHARGED/IN_REVIEW/CLOSED';
66	COMMENT ON COLUMN trip.frozen IS '复核冻结标志：TRUE 冻结中，FALSE 正常';
67	COMMENT ON COLUMN trip.created_at IS '创建时刻（UTC）';
68	COMMENT ON COLUMN trip.updated_at IS '最近更新时刻（UTC）';
69	
70	-- 在航护栏：每艘渔船至多一个未结案航次；出港时插入，结案时删除（数据库级唯一受理）
71	CREATE TABLE IF NOT EXISTS vessel_active_trip (
72	    vessel_code VARCHAR(32) NOT NULL PRIMARY KEY,
73	    trip_code   VARCHAR(48) NOT NULL
74	);
75	COMMENT ON TABLE vessel_active_trip IS '在航护栏：每艘渔船至多一个未结案航次';
76	COMMENT ON COLUMN vessel_active_trip.vessel_code IS '渔船编号（进行中航次唯一）';
77	COMMENT ON COLUMN vessel_active_trip.trip_code IS '当前进行中航次业务编号';
78	
79	-- 出港申报分鱼种数量
80	CREATE TABLE IF NOT EXISTS departure_line (
81	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
82	    trip_code   VARCHAR(48)   NOT NULL,
83	    species_code VARCHAR(32)  NOT NULL,
84	    weight_kg   DECIMAL(14,3) NOT NULL
85	);
86	CREATE INDEX IF NOT EXISTS idx_dep_line_trip ON departure_line (trip_code);
87	COMMENT ON TABLE departure_line IS '出港申报分鱼种数量';
88	COMMENT ON COLUMN departure_line.trip_code IS '航次业务编号';
89	COMMENT ON COLUMN departure_line.species_code IS '鱼种编号';
90	COMMENT ON COLUMN departure_line.weight_kg IS '申报捕捞量（千克）';
91	
92	-- 渔捞日志：按 UTC 日界归属，按“船＋日期＋渔区”唯一去重
93	CREATE TABLE IF NOT EXISTS logbook (
94	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
95	    trip_code    VARCHAR(48)   NOT NULL,
96	    vessel_code  VARCHAR(32)   NOT NULL,
97	    zone_code    VARCHAR(32)   NOT NULL,
98	    log_date     DATE          NOT NULL,
99	    fishing_at   TIMESTAMP(6)  NOT NULL,
100	    total_kg     DECIMAL(14,3) NOT NULL,
101	    bycatch_flag BOOLEAN       NOT NULL DEFAULT FALSE,
102	    late         BOOLEAN       NOT NULL DEFAULT FALSE,
103	    seq_no       INT           NOT NULL,
104	    created_at   TIMESTAMP(6) NOT NULL,
105	    CONSTRAINT uq_log_vessel_date_zone UNIQUE (vessel_code, log_date, zone_code)
106	);
107	CREATE INDEX IF NOT EXISTS idx_log_trip_time ON logbook (trip_code, fishing_at);
108	COMMENT ON TABLE logbook IS '渔捞日志：按 UTC 日界归属，按船＋日期＋渔区唯一去重';
109	COMMENT ON COLUMN logbook.trip_code IS '航次业务编号';
110	COMMENT ON COLUMN logbook.vessel_code IS '渔船编号';
111	COMMENT ON COLUMN logbook.zone_code IS '渔区编号';
112	COMMENT ON COLUMN logbook.log_date IS '作业归属日期（UTC 日界）';
113	COMMENT ON COLUMN logbook.fishing_at IS '实际作业时刻（UTC）';
114	COMMENT ON COLUMN logbook.total_kg IS '本日志总渔获量（千克）';
115	COMMENT ON COLUMN logbook.bycatch_flag IS '兼捕保护鱼种超 5% 单独标注：TRUE 是，FALSE 否';
116	COMMENT ON COLUMN logbook.late IS '结案后迟到日志标志：TRUE 迟到（仅入审查队列）';
117	COMMENT ON COLUMN logbook.seq_no IS '航次内按作业时刻排序的日志链序号（乱序归位）';
118	COMMENT ON COLUMN logbook.created_at IS '提交时刻（UTC）';
119	
120	-- 渔捞日志分鱼种数量
121	CREATE TABLE IF NOT EXISTS logbook_line (
122	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
123	    logbook_id  BIGINT        NOT NULL,
124	    species_code VARCHAR(32)  NOT NULL,
125	    weight_kg   DECIMAL(14,3) NOT NULL
126	);
127	CREATE INDEX IF NOT EXISTS idx_log_line_logbook ON logbook_line (logbook_id);
128	COMMENT ON TABLE logbook_line IS '渔捞日志分鱼种数量';
129	COMMENT ON COLUMN logbook_line.logbook_id IS '日志主键';
130	COMMENT ON COLUMN logbook_line.species_code IS '鱼种编号';
131	COMMENT ON COLUMN logbook_line.weight_kg IS '该鱼种渔获量（千克）';
132	
133	-- 结案后迟到日志事件（不参与核销，只入审查队列）
134	CREATE TABLE IF NOT EXISTS late_log_event (
135	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
136	    trip_code   VARCHAR(48)   NOT NULL,
137	    vessel_code VARCHAR(32)   NOT NULL,
138	    zone_code   VARCHAR(32)   NOT NULL,
139	    log_date    DATE          NOT NULL,
140	    fishing_at  TIMESTAMP(6)  NOT NULL,
141	    payload     CLOB          NOT NULL,
142	    created_at  TIMESTAMP(6)  NOT NULL
143	);
144	COMMENT ON TABLE late_log_event IS '结案后迟到日志事件（不参与核销，只入审查队列）';
145	COMMENT ON COLUMN late_log_event.trip_code IS '航次业务编号';
146	COMMENT ON COLUMN late_log_event.vessel_code IS '渔船编号';
147	COMMENT ON COLUMN late_log_event.zone_code IS '渔区编号';
148	COMMENT ON COLUMN late_log_event.log_date IS '作业归属日期（UTC 日界）';
149	COMMENT ON COLUMN late_log_event.fishing_at IS '实际作业时刻（UTC）';
150	COMMENT ON COLUMN late_log_event.payload IS '迟到日志原始报文（JSON）';
151	COMMENT ON COLUMN late_log_event.created_at IS '收到时刻（UTC）';
152	
153	-- 进港卸渔报告
154	CREATE TABLE IF NOT EXISTS landing (
155	    id                    BIGINT AUTO_INCREMENT PRIMARY KEY,
156	    trip_code             VARCHAR(48)   NOT NULL,
157	    landed_at             TIMESTAMP(6)  NOT NULL,
158	    total_kg              DECIMAL(14,3) NOT NULL,
159	    deviation_pct         DECIMAL(9,4)  NOT NULL,
160	    review_triggered      BOOLEAN       NOT NULL DEFAULT FALSE,
161	    deviation_explanation VARCHAR(512)  NULL,
162	    created_at            TIMESTAMP(6)  NOT NULL,
163	    CONSTRAINT uq_landing_trip UNIQUE (trip_code)
164	);
165	COMMENT ON TABLE landing IS '进港卸渔报告';
166	COMMENT ON COLUMN landing.trip_code IS '航次业务编号';
167	COMMENT ON COLUMN landing.landed_at IS '进港时刻（UTC）';
168	COMMENT ON COLUMN landing.total_kg IS '卸渔总量（千克）';
169	COMMENT ON COLUMN landing.deviation_pct IS '与日志累计量最大鱼种偏差（百分比，3.0000 表示 3%）';
170	COMMENT ON COLUMN landing.review_triggered IS '偏差超 3% 转复核：TRUE 是，FALSE 否';
171	COMMENT ON COLUMN landing.deviation_explanation IS '差异说明（偏差超 3% 时必填）';
172	COMMENT ON COLUMN landing.created_at IS '提交时刻（UTC）';
173	
174	-- 进港卸渔分鱼种数量
175	CREATE TABLE IF NOT EXISTS landing_line (
176	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
177	    landing_id  BIGINT        NOT NULL,
178	    species_code VARCHAR(32)  NOT NULL,
179	    weight_kg   DECIMAL(14,3) NOT NULL
180	);
181	CREATE INDEX IF NOT EXISTS idx_land_line_landing ON landing_line (landing_id);
182	COMMENT ON TABLE landing_line IS '进港卸渔分鱼种数量';
183	COMMENT ON COLUMN landing_line.landing_id IS '卸渔报告主键';
184	COMMENT ON COLUMN landing_line.species_code IS '鱼种编号';
185	COMMENT ON COLUMN landing_line.weight_kg IS '该鱼种卸渔量（千克）';
186	
187	-- 航次分鱼种口径量（核销依据）：logged_kg 日志累计，landed_kg 卸渔量，final_kg 最终口径
188	CREATE TABLE IF NOT EXISTS trip_catch_line (
189	    trip_code    VARCHAR(48)   NOT NULL,
190	    species_code VARCHAR(32)   NOT NULL,
191	    logged_kg    DECIMAL(14,3) NOT NULL DEFAULT 0,
192	    landed_kg    DECIMAL(14,3) NOT NULL DEFAULT 0,
193	    final_kg     DECIMAL(14,3) NOT NULL DEFAULT 0,
194	    CONSTRAINT pk_trip_catch PRIMARY KEY (trip_code, species_code)
195	);
196	COMMENT ON TABLE trip_catch_line IS '航次分鱼种口径量（核销依据）';
197	COMMENT ON COLUMN trip_catch_line.trip_code IS '航次业务编号';
198	COMMENT ON COLUMN trip_catch_line.species_code IS '鱼种编号';
199	COMMENT ON COLUMN trip_catch_line.logged_kg IS '日志累计量（千克）';
200	COMMENT ON COLUMN trip_catch_line.landed_kg IS '进港卸渔量（千克）';
201	COMMENT ON COLUMN trip_catch_line.final_kg IS '核销最终口径量（千克）';
202	
203	-- 人工复核案件
204	CREATE TABLE IF NOT EXISTS review_case (
205	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
206	    trip_code   VARCHAR(48)  NOT NULL,
207	    vessel_code VARCHAR(32)  NOT NULL,
208	    reason      VARCHAR(24)  NOT NULL,
209	    status      VARCHAR(8)   NOT NULL,
210	    conclusion  VARCHAR(24)  NULL,
211	    note        VARCHAR(512) NULL,
212	    created_at  TIMESTAMP(6) NOT NULL,
213	    decided_at  TIMESTAMP(6) NULL
214	);
215	CREATE INDEX IF NOT EXISTS idx_review_vessel_status ON review_case (vessel_code, status);
216	CREATE INDEX IF NOT EXISTS idx_review_trip_status ON review_case (trip_code, status);
217	COMMENT ON TABLE review_case IS '人工复核案件';
218	COMMENT ON COLUMN review_case.trip_code IS '航次业务编号';
219	COMMENT ON COLUMN review_case.vessel_code IS '渔船编号';
220	COMMENT ON COLUMN review_case.reason IS '触发原因：BYCATCH_RATIO/LANDING_DEVIATION/LATE_LOG';
221	COMMENT ON COLUMN review_case.status IS '状态：OPEN/CLOSED';
222	COMMENT ON COLUMN review_case.conclusion IS '最终结论：CONFIRM_LANDED/CONFIRM_LOGGED/ADJUSTED';
223	COMMENT ON COLUMN review_case.note IS '复核备注/差异说明';
224	COMMENT ON COLUMN review_case.created_at IS '立案时刻（UTC）';
225	COMMENT ON COLUMN review_case.decided_at IS '结论时刻（UTC），未决为空';
226	
227	-- 配额核销明细（台账可复算）
228	CREATE TABLE IF NOT EXISTS settlement (
229	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
230	    trip_code   VARCHAR(48)   NOT NULL,
231	    vessel_code VARCHAR(32)   NOT NULL,
232	    quota_year  INT           NOT NULL,
233	    species_code VARCHAR(32)  NOT NULL,
234	    deducted_kg DECIMAL(14,3) NOT NULL,
235	    created_at  TIMESTAMP(6)  NOT NULL,
236	    CONSTRAINT uq_settlement_trip_species UNIQUE (trip_code, species_code)
237	);
238	COMMENT ON TABLE settlement IS '配额核销明细（台账可复算）';
239	COMMENT ON COLUMN settlement.trip_code IS '航次业务编号';
240	COMMENT ON COLUMN settlement.vessel_code IS '渔船编号';
241	COMMENT ON COLUMN settlement.quota_year IS '核销年度（UTC）';
242	COMMENT ON COLUMN settlement.species_code IS '鱼种编号';
243	COMMENT ON COLUMN settlement.deducted_kg IS '本次核销扣减量（千克）';
244	COMMENT ON COLUMN settlement.created_at IS '核销时刻（UTC）';
245	
246	-- 幂等请求台账：request_id 主键，指纹覆盖 requestId 之外全部业务字段
247	CREATE TABLE IF NOT EXISTS idempotency_record (
248	    request_id    VARCHAR(64)  NOT NULL PRIMARY KEY,
249	    operation     VARCHAR(24)  NOT NULL,
250	    fingerprint   CHAR(64)     NOT NULL,
251	    response_json CLOB         NULL,
252	    created_at    TIMESTAMP(6) NOT NULL
253	);
254	COMMENT ON TABLE idempotency_record IS '幂等请求台账：request_id 主键';
255	COMMENT ON COLUMN idempotency_record.request_id IS '幂等键 requestId';
256	COMMENT ON COLUMN idempotency_record.operation IS '操作类型';
257	COMMENT ON COLUMN idempotency_record.fingerprint IS '业务参数指纹（SHA-256 十六进制）';
258	COMMENT ON COLUMN idempotency_record.response_json IS '首次成功结果快照（JSON），受理中为空';
259	COMMENT ON COLUMN idempotency_record.created_at IS '首次受理时刻（UTC）';
260

