62	/**
63	 * 渔业捕捞配额与渔捞日志核销应用服务。
64	 *
65	 * <p>关键口径：兼捕保护鱼种占比恰 5% 合法，严格大于才标注并审查；卸渔偏差恰 3% 视为一致，
66	 * 严格大于才需差异说明并转复核；申报量累计恰达配额合法，任鱼种超出则整笔拒绝。
67	 */
68	@Service
69	public class FisheryService {
70	
71	    /** 兼捕保护鱼种允许比例（含边界，恰 5% 合法）。 */
72	    static final BigDecimal BYCATCH_LIMIT_PCT = new BigDecimal("5.0000");
73	    /** 卸渔偏差允许比例（含边界，恰 3% 视为一致）。 */
74	    static final BigDecimal DEVIATION_LIMIT_PCT = new BigDecimal("3.0000");
75	
76	    private static final String OP_DEPARTURE = "DEPARTURE";
77	    private static final String OP_LOGBOOK = "LOGBOOK";
78	    private static final String OP_LANDING = "LANDING";
79	    private static final String OP_SETTLEMENT = "SETTLEMENT";
80	    private static final String OP_REVIEW_DECISION = "REVIEW_DECISION";
81	
82	    private final TripRepository tripRepo;
83	    private final LogbookRepository logbookRepo;
84	    private final LandingRepository landingRepo;
85	    private final ReviewRepository reviewRepo;
86	    private final QuotaRepository quotaRepo;
87	    private final CatalogRepository catalogRepo;
88	    private final IdempotencyRepository idempotencyRepo;
89	    private final ObjectMapper objectMapper;
90	    private final Clock clock;
91	
92	    public FisheryService(TripRepository tripRepo, LogbookRepository logbookRepo,
93	                          LandingRepository landingRepo, ReviewRepository reviewRepo,
94	                          QuotaRepository quotaRepo, CatalogRepository catalogRepo,
95	                          IdempotencyRepository idempotencyRepo, ObjectMapper objectMapper, Clock clock) {
96	        this.tripRepo = tripRepo;
97	        this.logbookRepo = logbookRepo;
98	        this.landingRepo = landingRepo;
99	        this.reviewRepo = reviewRepo;
100	        this.quotaRepo = quotaRepo;
101	        this.catalogRepo = catalogRepo;
102	        this.idempotencyRepo = idempotencyRepo;
103	        this.objectMapper = objectMapper;
104	        this.clock = clock;
105	    }
106	
107	    // ------------------------------------------------------------------
108	    // 出港申报
109	    // ------------------------------------------------------------------
110	
111	    @Transactional
112	    public DepartureResponse declareDeparture(DepartureRequest request) {
113	        String fingerprint = fingerprint(Map.of(
114	                "op", OP_DEPARTURE,
115	                "tripCode", request.tripCode(),
116	                "vesselCode", request.vesselCode(),
117	                "departAt", request.departAt().toString(),
118	                "lines", normalizedLines(request.lines().stream()
119	                        .map(l -> Map.of("speciesCode", l.speciesCode(), "weightKg", l.weightKg().toPlainString()))
120	                        .toList())));
121	        AcquireResult acquired = idempotencyRepo.acquire(
122	                request.requestId(), OP_DEPARTURE, fingerprint, Instant.now(clock));
123	        switch (acquired.outcome()) {
124	            case REPLAY -> {
125	                return replay(acquired.responseJson(), DepartureResponse.class);
126	            }
127	            case MISMATCH -> throw new ConflictException("相同 requestId 已用于不同业务参数");
128	            case IN_PROGRESS -> throw new ConflictException("相同 requestId 请求正在处理中");
129	            default -> { }
130	        }
131	
132	        requireVessel(request.vesselCode());
133	        Map<String, BigDecimal> declared = mergePositiveLines(request.lines().stream()
134	                .map(l -> new WeightLineView(l.speciesCode(), l.weightKg())).toList());
135	        declared.keySet().forEach(this::requireSpecies);
136	
137	        int year = utcYear(request.departAt());
138	        // 配额按鱼种分年度核定：单航次申报后该船该鱼种累计不得超配额，超出整笔拒绝。
139	        for (Map.Entry<String, BigDecimal> entry : declared.entrySet()) {
140	            SpeciesRow species = catalogRepo.findSpecies(entry.getKey());
141	            if (species != null && species.protectedSpecies()) {
142	                continue; // 兼捕保护鱼种不占用商业配额
143	            }
144	            QuotaRow quota = quotaRepo.findForUpdate(request.vesselCode(), entry.getKey(), year)
145	                    .orElse(null);
146	            BigDecimal quotaLimit = quota == null ? BigDecimal.ZERO : quota.quotaKg();
147	            BigDecimal used = quota == null ? BigDecimal.ZERO : quota.usedKg();
148	            BigDecimal cumulative = used.add(entry.getValue());
149	            if (cumulative.compareTo(quotaLimit) > 0) {
150	                throw new BusinessRuleException("申报量使渔船 " + request.vesselCode() + " 鱼种 "
151	                        + entry.getKey() + " " + year + " 年度累计 " + cumulative.toPlainString()
152	                        + "kg 超过配额 " + quotaLimit.toPlainString() + "kg，整笔拒绝");
153	            }
154	        }
155	
156	        // 同一渔船同时刻只允许一个进行中航次（数据库护栏保证并发唯一受理）。
157	        if (tripRepo.existsOpenForVessel(request.vesselCode())
158	                || !tripRepo.tryOccupyActiveVessel(request.vesselCode(), request.tripCode())) {
159	            throw new ConflictException("渔船 " + request.vesselCode() + " 已存在进行中航次，出港申报唯一受理");
160	        }
161	
162	        if (tripRepo.findByCode(request.tripCode()).isPresent()) {
163	            throw new ConflictException("航次编号 " + request.tripCode() + " 已存在");
164	        }
165	
166	        Instant now = Instant.now(clock);
167	        tripRepo.insert(new TripRow(null, request.tripCode(), request.vesselCode(),
168	                request.departAt(), null, TripStatus.DEPARTED, false, now, now));
169	        declared.forEach((speciesCode, weight) ->
170	                tripRepo.insertDepartureLine(request.tripCode(), speciesCode, weight));
171	
172	        DepartureResponse response = new DepartureResponse(request.tripCode(), request.vesselCode(),
173	                TripStatus.DEPARTED, request.departAt(), year, toViews(declared), false);
174	        idempotencyRepo.saveResponse(request.requestId(), toJson(response));
175	        return response;
176	    }
