373	    @Transactional
374	    public SettlementResponse settle(SettlementRequest request) {
375	        String fingerprint = fingerprint(Map.of("op", OP_SETTLEMENT, "tripCode", request.tripCode()));
376	        AcquireResult acquired = idempotencyRepo.acquire(
377	                request.requestId(), OP_SETTLEMENT, fingerprint, Instant.now(clock));
378	        switch (acquired.outcome()) {
379	            case REPLAY -> {
380	                return replay(acquired.responseJson(), SettlementResponse.class);
381	            }
382	            case MISMATCH -> throw new ConflictException("相同 requestId 已用于不同业务参数");
383	            case IN_PROGRESS -> throw new ConflictException("相同 requestId 请求正在处理中");
384	            default -> { }
385	        }
386	
387	        SettlementResponse response = doSettle(request.tripCode(), request.requestId());
388	        return response;
389	    }
390	
391	    /**
392	     * 核销与余额扣减、结案在同一事务内完成：配额行 FOR UPDATE 串行化并发核销，
393	     * 任鱼种余额不足则整笔回滚（不会出现余额已扣而航次未结案）。
394	     */
395	    private SettlementResponse doSettle(String tripCode, String requestId) {
396	        TripRow trip = requireTripForUpdate(tripCode);
397	        if (trip.status() == TripStatus.CLOSED) {
398	            // 结案为终态：重复结案返回幂等成功（返回首次核销明细）。
399	            SettlementResponse existing = buildSettlementResponse(trip, true);
400	            if (requestId != null) {
401	                idempotencyRepo.saveResponse(requestId, toJson(existing));
402	            }
403	            return existing;
404	        }
405	        if (reviewRepo.countOpenForTrip(tripCode) > 0 || trip.frozen()) {
406	            throw new ConflictException("航次 " + tripCode + " 复核期间配额余额冻结，暂不能核销");
407	        }
408	        if (landingRepo.findByTrip(tripCode).isEmpty()) {
409	            throw new BusinessRuleException("航次 " + tripCode + " 尚未进港报告，不能核销");
410	        }
411	
412	        int year = utcYear(trip.departAt());
413	        Map<String, BigDecimal> finalCatch = finalCatchMap(tripCode);
414	        Instant now = Instant.now(clock);
415	
416	        // 持锁校验并扣减，两航次并发核销同一配额不会合计超配额。
417	        List<WeightLineView> deducted = new ArrayList<>();
418	        for (Map.Entry<String, BigDecimal> entry : finalCatch.entrySet()) {
419	            SpeciesRow species = catalogRepo.findSpecies(entry.getKey());
420	            BigDecimal amount = entry.getValue();
421	            if (species != null && species.protectedSpecies()) {
422	                deducted.add(new WeightLineView(entry.getKey(), BigDecimal.ZERO.setScale(3)));
423	                continue;
424	            }
425	            QuotaRow quota = quotaRepo.findForUpdate(trip.vesselCode(), entry.getKey(), year)
426	                    .orElse(null);
427	            BigDecimal quotaLimit = quota == null ? BigDecimal.ZERO : quota.quotaKg();
428	            BigDecimal used = quota == null ? BigDecimal.ZERO : quota.usedKg();
429	            if (used.add(amount).compareTo(quotaLimit) > 0) {
430	                throw new BusinessRuleException("核销使渔船 " + trip.vesselCode() + " 鱼种 "
431	                        + entry.getKey() + " 累计 " + used.add(amount).toPlainString()
432	                        + "kg 超过配额 " + quotaLimit.toPlainString() + "kg，核销整笔回滚");
433	            }
434	            quotaRepo.deductLocked(quota, amount);
435	            quotaRepo.insertSettlement(tripCode, trip.vesselCode(), year, entry.getKey(), amount, now);
436	            deducted.add(new WeightLineView(entry.getKey(), amount.setScale(3, RoundingMode.HALF_UP)));
437	        }
438	        deducted.sort(Comparator.comparing(WeightLineView::speciesCode));
439	
440	        tripRepo.updateState(tripCode, TripStatus.CLOSED, false, now);
441	        tripRepo.releaseActiveVessel(trip.vesselCode());
442	
443	        SettlementResponse response = new SettlementResponse(tripCode, trip.vesselCode(),
444	                TripStatus.CLOSED, year, deducted, false);
445	        if (requestId != null) {
446	            idempotencyRepo.saveResponse(requestId, toJson(response));
447	        }
448	        return response;
449	    }
450	
451	    private SettlementResponse buildSettlementResponse(TripRow trip, boolean replayed) {
452	        int year = utcYear(trip.departAt());
453	        List<WeightLineView> deducted = quotaRepo.findSettlements(trip.tripCode()).stream()
454	                .map(s -> new WeightLineView(s.speciesCode(), s.deductedKg()))
455	                .toList();
456	        return new SettlementResponse(trip.tripCode(), trip.vesselCode(), TripStatus.CLOSED,
457	                year, deducted, replayed);
458	    }
