460	    // ------------------------------------------------------------------
461	    // 人工复核结论
462	    // ------------------------------------------------------------------
463	
464	    @Transactional
465	    public ReviewDecisionResponse decideReview(Long reviewId, ReviewDecisionRequest request) {
466	        String fingerprint = fingerprint(Map.of(
467	                "op", OP_REVIEW_DECISION,
468	                "reviewId", reviewId.toString(),
469	                "conclusion", request.conclusion().name(),
470	                "note", request.note() == null ? "" : request.note(),
471	                "lines", normalizedLines((request.adjustedLines() == null ? List.<ReviewDecisionRequest.AdjustedLine>of()
472	                        : request.adjustedLines()).stream()
473	                        .map(l -> Map.of("speciesCode", l.speciesCode(), "weightKg", l.weightKg().toPlainString()))
474	                        .toList())));
475	        AcquireResult acquired = idempotencyRepo.acquire(
476	                request.requestId(), OP_REVIEW_DECISION, fingerprint, Instant.now(clock));
477	        switch (acquired.outcome()) {
478	            case REPLAY -> {
479	                return replay(acquired.responseJson(), ReviewDecisionResponse.class);
480	            }
481	            case MISMATCH -> throw new ConflictException("相同 requestId 已用于不同业务参数");
482	            case IN_PROGRESS -> throw new ConflictException("相同 requestId 请求正在处理中");
483	            default -> { }
484	        }
485	
486	        ReviewRow review = reviewRepo.findByIdForUpdate(reviewId)
487	                .orElseThrow(() -> new NotFoundException("复核案件 " + reviewId + " 不存在"));
488	        if (review.status() == ReviewStatus.CLOSED) {
489	            throw new ConflictException("复核案件 " + reviewId + " 已有最终结论");
490	        }
491	        TripRow trip = requireTripForUpdate(review.tripCode());
492	
493	        Map<String, BigDecimal> adjusted = request.adjustedLines() == null
494	                ? Map.of()
495	                : mergePositiveLines(request.adjustedLines().stream()
496	                        .map(l -> new WeightLineView(l.speciesCode(), l.weightKg())).toList());
497	        if (request.conclusion() == ReviewConclusion.ADJUSTED && adjusted.isEmpty()) {
498	            throw new BusinessRuleException("复核结论为 ADJUSTED 时必须提供分鱼种最终数量");
499	        }
500	
501	        String note = request.note() == null ? review.note() : request.note();
502	        Instant now = Instant.now(clock);
503	
504	        // 结案为终态：结案后迟到日志案件的结论只关闭审查队列，不改口径、不重新核销、不改航次状态。
505	        if (trip.status() == TripStatus.CLOSED) {
506	            reviewRepo.close(reviewId, request.conclusion(), note, now);
507	            ReviewRow closedCase = reviewRepo.findById(reviewId).orElseThrow();
508	            ReviewDecisionResponse response = new ReviewDecisionResponse(
509	                    reviewId, trip.tripCode(), toView(closedCase), false,
510	                    reviewRepo.countOpenForVessel(trip.vesselCode()), false, null,
511	                    TripStatus.CLOSED, false);
512	            idempotencyRepo.saveResponse(request.requestId(), toJson(response));
513	            return response;
514	        }
515	
516	        // 复核结论为最终口径：按结论重算各鱼种 final_kg。
517	        Map<String, BigDecimal> logged = effectiveLoggedMap(trip.tripCode());
518	        Map<String, BigDecimal> landed = tripRepo.findCatchLines(trip.tripCode()).stream()
519	                .collect(LinkedHashMap::new,
520	                        (m, c) -> m.put(c.speciesCode(), c.landedKg()),
521	                        LinkedHashMap::putAll);
522	        Map<String, BigDecimal> finalCatch = new LinkedHashMap<>();
523	        logged.forEach((speciesCode, weight) -> {
524	            BigDecimal finalWeight = switch (request.conclusion()) {
525	                case CONFIRM_LANDED -> landed.getOrDefault(speciesCode, BigDecimal.ZERO);
526	                case CONFIRM_LOGGED -> weight;
527	                case ADJUSTED -> adjusted.getOrDefault(speciesCode, weight);
528	            };
529	            finalCatch.put(speciesCode, finalWeight);
530	        });
531	        if (request.conclusion() == ReviewConclusion.ADJUSTED) {
532	            adjusted.forEach(finalCatch::putIfAbsent);
533	        }
534	        finalCatch.forEach((speciesCode, weight) ->
535	                tripRepo.updateFinalKg(trip.tripCode(), speciesCode, weight));
536	
537	        reviewRepo.close(reviewId, request.conclusion(), note, now);
538	
539	        long openReviews = reviewRepo.countOpenForVessel(trip.vesselCode());
540	        boolean frozen = openReviews > 0;
541	        // 冻结与复核结论在同一事务内解除；无未决案件且已进港则同事务核销结案。
542	        boolean canSettle = openReviews == 0 && landingRepo.findByTrip(trip.tripCode()).isPresent();
543	        SettlementResponse settlement = null;
544	        TripStatus resultingStatus;
545	        if (canSettle) {
546	            // 同一事务内先解除冻结（无未决案件），再核销结案；任一失败整体回滚。
547	            tripRepo.updateState(trip.tripCode(), TripStatus.DISCHARGED, false, now);
548	            settlement = doSettle(trip.tripCode(), null);
549	            resultingStatus = TripStatus.CLOSED;
550	        } else if (openReviews > 0) {
551	            resultingStatus = TripStatus.IN_REVIEW;
552	            tripRepo.updateState(trip.tripCode(), resultingStatus, true, now);
553	        } else {
554	            // 无未决复核：按是否已进港回到 DISCHARGED 或 DEPARTED，并同事务解除冻结。
555	            resultingStatus = landingRepo.findByTrip(trip.tripCode()).isPresent()
556	                    ? TripStatus.DISCHARGED : TripStatus.DEPARTED;
557	            tripRepo.updateState(trip.tripCode(), resultingStatus, false, now);
558	        }
559	
560	        ReviewRow closed = reviewRepo.findById(reviewId).orElseThrow();
561	        ReviewDecisionResponse response = new ReviewDecisionResponse(
562	                reviewId, trip.tripCode(), toView(closed), resultingStatus == TripStatus.IN_REVIEW,
563	                openReviews, settlement != null, settlement, resultingStatus, false);
564	        idempotencyRepo.saveResponse(request.requestId(), toJson(response));
565	        return response;
566	    }
