568	    // ------------------------------------------------------------------
569	    // 复算与台账查询
570	    // ------------------------------------------------------------------
571	
572	    @Transactional(readOnly = true)
573	    public ReconcileResponse reconcile(String tripCode) {
574	        TripRow trip = requireTrip(tripCode);
575	        int year = utcYear(trip.departAt());
576	
577	        Map<String, BigDecimal> declared = new LinkedHashMap<>(
578	                tripRepo.findDepartureLines(tripCode).stream()
579	                        .collect(LinkedHashMap::new,
580	                                (m, l) -> m.put(l.speciesCode(), l.weightKg()),
581	                                LinkedHashMap::putAll));
582	        Map<String, BigDecimal> logged = effectiveLoggedMap(tripCode);
583	        Map<String, BigDecimal> landed = new LinkedHashMap<>();
584	        landingRepo.findByTrip(tripCode).ifPresent(landing ->
585	                landingRepo.findLines(landing.id()).forEach(l -> landed.put(l.speciesCode(), l.weightKg())));
586	        Map<String, BigDecimal> finalKg = finalCatchMap(tripCode);
587	        Map<String, BigDecimal> deducted = new LinkedHashMap<>();
588	        quotaRepo.findSettlements(tripCode).forEach(s -> deducted.put(s.speciesCode(), s.deductedKg()));
589	
590	        List<String> species = new ArrayList<>();
591	        for (Map<String, BigDecimal> source : List.of(declared, logged, landed, finalKg, deducted)) {
592	            for (String code : source.keySet()) {
593	                if (!species.contains(code)) {
594	                    species.add(code);
595	                }
596	            }
597	        }
598	        species.sort(Comparator.naturalOrder());
599	
600	        List<ReconcileLine> lines = species.stream()
601	                .map(code -> new ReconcileLine(
602	                        code,
603	                        declared.getOrDefault(code, BigDecimal.ZERO).setScale(3, RoundingMode.HALF_UP),
604	                        logged.getOrDefault(code, BigDecimal.ZERO).setScale(3, RoundingMode.HALF_UP),
605	                        landed.getOrDefault(code, BigDecimal.ZERO).setScale(3, RoundingMode.HALF_UP),
606	                        finalKg.getOrDefault(code, BigDecimal.ZERO).setScale(3, RoundingMode.HALF_UP),
607	                        deducted.getOrDefault(code, BigDecimal.ZERO).setScale(3, RoundingMode.HALF_UP)))
608	                .toList();
609	
610	        // 台账复算：used_kg 必须等于该船该年度全部核销明细合计。
611	        boolean ledgerConsistent = quotaRepo.findByVesselYear(trip.vesselCode(), year).stream()
612	                .allMatch(q -> q.usedKg().compareTo(
613	                        quotaRepo.sumSettled(trip.vesselCode(), q.speciesCode(), year)) == 0);
614	        boolean hasDeduction = !deducted.isEmpty();
615	        // 不得出现余额已扣而航次未结案。
616	        boolean settledAndClosed = !hasDeduction || trip.status() == TripStatus.CLOSED;
617	
618	        List<ReviewCaseView> reviews = reviewRepo.findByTrip(tripCode).stream()
619	                .map(this::toView).toList();
620	        return new ReconcileResponse(tripCode, trip.vesselCode(), year, trip.status(), trip.frozen(),
621	                lines, reviews, ledgerConsistent, settledAndClosed
622	                        && logbookRepo.chainIsContiguous(tripCode));
623	    }
624	
625	    @Transactional(readOnly = true)
626	    public List<QuotaView> quotas(String vesselCode, Integer year) {
627	        if (vesselCode == null) {
628	            return List.of();
629	        }
630	        List<QuotaRow> rows = year == null
631	                ? quotaRepo.findByVessel(vesselCode)
632	                : quotaRepo.findByVesselYear(vesselCode, year);
633	        return rows.stream()
634	                .map(q -> new QuotaView(q.vesselCode(), q.speciesCode(), q.year(), q.quotaKg(),
635	                        q.usedKg(), q.quotaKg().subtract(q.usedKg())))
636	                .toList();
637	    }
638	
639	    // ------------------------------------------------------------------
640	    // 辅助方法
641	    // ------------------------------------------------------------------
642	
643	    private void recomputeLoggedCatch(String tripCode) {
644	        effectiveLoggedMap(tripCode).forEach((speciesCode, weight) ->
645	                tripRepo.updateLoggedKg(tripCode, speciesCode, weight));
646	    }
647	
648	    private Map<String, BigDecimal> effectiveLoggedMap(String tripCode) {
649	        Map<String, BigDecimal> map = new LinkedHashMap<>();
650	        logbookRepo.sumEffectiveLines(tripCode).forEach(l -> map.put(l.speciesCode(), l.weightKg()));
651	        return map;
652	    }
653	
654	    /** 核销最终口径：有口径行以 final_kg 为准，未生成时回退日志累计量。 */
655	    private Map<String, BigDecimal> finalCatchMap(String tripCode) {
656	        Map<String, BigDecimal> map = new LinkedHashMap<>();
657	        tripRepo.findCatchLines(tripCode).forEach(c -> {
658	            if (c.finalKg() != null && c.finalKg().compareTo(BigDecimal.ZERO) > 0) {
659	                map.put(c.speciesCode(), c.finalKg());
660	            } else if (c.loggedKg() != null && c.loggedKg().compareTo(BigDecimal.ZERO) > 0) {
661	                map.put(c.speciesCode(), c.loggedKg());
662	            }
663	        });
664	        return map;
665	    }
666	
667	    private void requireVessel(String vesselCode) {
668	        if (catalogRepo.findVessel(vesselCode) == null) {
669	            throw new NotFoundException("渔船 " + vesselCode + " 不存在");
670	        }
671	    }
672	
673	    private void requireSpecies(String speciesCode) {
674	        if (catalogRepo.findSpecies(speciesCode) == null) {
675	            throw new NotFoundException("鱼种 " + speciesCode + " 不存在");
676	        }
677	    }
678	
679	    private TripRow requireTrip(String tripCode) {
680	        return tripRepo.findByCode(tripCode)
681	                .orElseThrow(() -> new NotFoundException("航次 " + tripCode + " 不存在"));
682	    }
683	
684	    private TripRow requireTripForUpdate(String tripCode) {
685	        return tripRepo.findByCodeForUpdate(tripCode)
686	                .orElseThrow(() -> new NotFoundException("航次 " + tripCode + " 不存在"));
687	    }
688	
689	    private static int utcYear(Instant instant) {
690	        return instant.atZone(ZoneOffset.UTC).getYear();
691	    }
692	
693	    /** 合并同鱼种数量（防御性，请求内同鱼种多行时累加）。 */
694	    private Map<String, BigDecimal> mergePositiveLines(List<WeightLineView> lines) {
695	        Map<String, BigDecimal> merged = new LinkedHashMap<>();
696	        for (WeightLineView line : lines) {
697	            if (line.weightKg().signum() <= 0) {
698	                throw new BusinessRuleException("鱼种 " + line.speciesCode() + " 数量必须大于 0");
699	            }
700	            merged.merge(line.speciesCode(), line.weightKg(), BigDecimal::add);
701	        }
702	        return merged;
703	    }
704	
705	    private List<WeightLineView> toViews(Map<String, BigDecimal> weights) {
706	        return weights.entrySet().stream()
707	                .sorted(Map.Entry.comparingByKey())
708	                .map(e -> new WeightLineView(e.getKey(), e.getValue().setScale(3, RoundingMode.HALF_UP)))
709	                .toList();
710	    }
711	
712	    private ReviewCaseView toView(ReviewRow row) {
713	        return new ReviewCaseView(row.id(), row.reason(), row.status(), row.conclusion(),
714	                row.note(), row.createdAt(), row.decidedAt());
715	    }
716	
717	    /** 规范化业务字段（行按鱼种排序）后再哈希，避免行序影响指纹。 */
718	    private List<Map<String, String>> normalizedLines(List<Map<String, String>> lines) {
719	        return lines.stream()
720	                .sorted(Comparator.comparing(m -> m.get("speciesCode")))
721	                .map(TreeMap::new)
722	                .map(m -> (Map<String, String>) m)
723	                .toList();
724	    }
725	
726	    private String fingerprint(Object canonicalPayload) {
727	        try {
728	            String json = objectMapper.writer()
729	                    .with(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS)
730	                    .writeValueAsString(canonicalPayload);
731	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
732	            byte[] hash = digest.digest(json.getBytes(StandardCharsets.UTF_8));
733	            StringBuilder hex = new StringBuilder();
734	            for (byte b : hash) {
735	                hex.append(String.format("%02x", b));
736	            }
737	            return hex.toString();
738	        } catch (JsonProcessingException | NoSuchAlgorithmException ex) {
739	            throw new IllegalStateException("生成幂等指纹失败", ex);
740	        }
741	    }
742	
743	    private String toJson(Object response) {
744	        try {
745	            return objectMapper.writeValueAsString(response);
746	        } catch (JsonProcessingException ex) {
747	            throw new IllegalStateException("序列化响应快照失败", ex);
748	        }
749	    }
750	
751	    private <T> T replay(String json, Class<T> type) {
752	        if (json == null) {
753	            throw new ConflictException("首次请求尚未处理完成");
754	        }
755	        try {
756	            T value = objectMapper.readValue(json, type);
757	            if (value instanceof com.example.starter.fishery.api.dto.ReplayAware replayAware) {
758	                @SuppressWarnings("unchecked")
759	                T marked = (T) replayAware.withReplayed(true);
760	                return marked;
761	            }
762	            return value;
763	        } catch (JsonProcessingException ex) {
764	            throw new IllegalStateException("读取首次响应快照失败", ex);
765	        }
766	    }
767	}
