54	    /** 查询渔船某年度全部配额台账（可复算）。 */
55	    public List<QuotaRow> findByVesselYear(String vesselCode, int year) {
56	        return jdbc.query(
57	                "SELECT " + QUOTA_COLUMNS + " FROM quota "
58	                        + "WHERE vessel_code = ? AND quota_year = ? ORDER BY species_code",
