65	                "SELECT " + QUOTA_COLUMNS + " FROM quota "
66	                        + "WHERE vessel_code = ? ORDER BY quota_year, species_code",
67	                QUOTA_MAPPER, vesselCode);
68	    }
69	
70	    /**
71	     * 事务内行锁读取年度配额；并发核销时串行化同一（船，鱼种，年度）扣减。
72	     * 不存在返回空（该鱼该年度无核定配额即按 0 处理）。
73	     */
74	    public Optional<QuotaRow> findForUpdate(String vesselCode, String speciesCode, int year) {
75	        List<QuotaRow> rows = jdbc.query(
76	                "SELECT " + QUOTA_COLUMNS + " FROM quota "
77	                        + "WHERE vessel_code = ? AND species_code = ? AND quota_year = ? FOR UPDATE",
78	                QUOTA_MAPPER, vesselCode, speciesCode, year);
79	        return rows.stream().findFirst();
80	    }
81	
82	    /** 新增年度配额（合成数据维护用）。 */
83	    public void insert(String vesselCode, String speciesCode, int year, BigDecimal quotaKg) {
84	        jdbc.update("INSERT INTO quota(vessel_code, species_code, quota_year, quota_kg, used_kg, version) "
85	                + "VALUES (?, ?, ?, ?, 0, 0)", vesselCode, speciesCode, year, quotaKg);
86	    }
87	
88	    /** 在已持有的配额行锁上直接扣减；调用方须先校验扣减后不超配额。 */
89	    public void deductLocked(QuotaRow quota, BigDecimal amount) {
90	        int updated = jdbc.update(
91	                "UPDATE quota SET used_kg = used_kg + ?, version = version + 1 "
92	                        + "WHERE vessel_code = ? AND species_code = ? AND quota_year = ? AND version = ?",
93	                amount, quota.vesselCode(), quota.speciesCode(), quota.year(), quota.version());
94	        if (updated != 1) {
95	            throw new IllegalStateException("配额台账乐观锁冲突: " + quota.vesselCode()
96	                    + "/" + quota.speciesCode() + "/" + quota.year());
97	        }
98	    }
99	
100	    /** 写入核销明细。 */
101	    public void insertSettlement(String tripCode, String vesselCode, int year,
102	                                 String speciesCode, BigDecimal deductedKg, Instant createdAt) {
103	        jdbc.update("INSERT INTO settlement(trip_code, vessel_code, quota_year, species_code, "
104	                + "deducted_kg, created_at) VALUES (?, ?, ?, ?, ?, ?)",
105	                tripCode, vesselCode, year, speciesCode, deductedKg, Timestamp.from(createdAt));
106	    }
