108	    /** 查询航次核销明细。 */
109	    public List<SettlementRow> findSettlements(String tripCode) {
110	        return jdbc.query(
111	                "SELECT id, trip_code, vessel_code, quota_year, species_code, deducted_kg, created_at "
112	                        + "FROM settlement WHERE trip_code = ? ORDER BY species_code",
113	                SETTLEMENT_MAPPER, tripCode);
114	    }
115	
116	    /** 某船某鱼种某年度全部已结案核销明细合计（台账复算用）。 */
117	    public BigDecimal sumSettled(String vesselCode, String speciesCode, int year) {
118	        BigDecimal sum = jdbc.queryForObject(
119	                "SELECT COALESCE(SUM(deducted_kg), 0) FROM settlement "
120	                        + "WHERE vessel_code = ? AND species_code = ? AND quota_year = ?",
121	                BigDecimal.class, vesselCode, speciesCode, year);
