        return service.reconcile(tripCode);
    }

    @GetMapping("/quotas")
    public List<QuotaView> quotas(@RequestParam(required = false) String vesselCode,
                                  @RequestParam(required = false) Integer year) {
        return service.quotas(vesselCode, year);
    }
}

