69	        Integer count = jdbcTemplate.queryForObject(
70	                "SELECT COUNT(1) FROM quota WHERE vessel_code = ? AND species_code = ? AND quota_year = ?",
71	                Integer.class, vesselCode, speciesCode, year);
72	        if (count == null || count == 0) {
73	            jdbcTemplate.update(
74	                    "INSERT INTO quota(vessel_code, species_code, quota_year, quota_kg, used_kg, version) "
75	                            + "VALUES (?, ?, ?, ?, 0, 0)",
76	                    vesselCode, speciesCode, year, quotaKg);
77	        }
78	    }
79	}
