package com.example.starter.fishery.domain;

/**
 * 跨船配额调剂单状态，流转：PENDING（待双方确认）→ EFFECTIVE（双方确认生效）；
 * 确认时限 48 小时（UTC）恰满仍未双方确认则自动失效为 EXPIRED，失效单可重新发起。
 */
public enum TransferStatus {
    /** 待双方确认（进行中）。 */
    PENDING,
    /** 双方已确认，调剂生效且双方额度已同事务变更。 */
    EFFECTIVE,
    /** 确认时限恰满未确认，自动失效，额度不变。 */
    EXPIRED
}

package com.example.starter.fishery.db;

import com.example.starter.fishery.domain.TransferStatus;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 跨船配额调剂单行：{@code amountKg} 为调剂量（千克），{@code expiresAt} 为确认截止时刻
 * （UTC，发起后 48 小时），{@code effectiveAt} 未生效为空。
 */
public record TransferRow(
        Long id,
        String fromVessel,
        String toVessel,
        String speciesCode,
        int quotaYear,
        BigDecimal amountKg,
        TransferStatus status,
        boolean fromConfirmed,
        boolean toConfirmed,
        Instant createdAt,
        Instant expiresAt,
        Instant effectiveAt,
        int version) {
}

package com.example.starter.fishery.db;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 年度结转台账行：{@code amountKg} 为结转额度（千克，不超过来源年度核定配额的 20%），
 * {@code usedKg} 为次年优先核销已扣减量（千克）。
 */
public record CarryoverRow(
        Long id,
        String vesselCode,
        String speciesCode,
        int fromYear,
        int toYear,
        BigDecimal amountKg,
        BigDecimal usedKg,
        Instant createdAt) {
}

package com.example.starter.fishery.db;

import java.math.BigDecimal;

/**
 * 配额台账行：船＋鱼种＋UTC 年度核定，{@code quotaKg} 为年度配额（千克，不含结转），
 * {@code usedKg} 为已核销扣减数量（千克，不含结转核销），
 * {@code alertTriggered} 为产地预警标志（TRUE 时该额度不得结转），{@code version} 为乐观锁版本号。
 */
public record QuotaRow(
        String vesselCode,
        String speciesCode,
        int year,
        BigDecimal quotaKg,
        BigDecimal usedKg,
        boolean alertTriggered,
        int version) {
}

