BigDecimal used = quota == null ? BigDecimal.ZERO : quota.usedKg();
// 结转额度次年优先核销：可用额度 = 年度配额剩余 + 结转剩余。
List<CarryoverRow> carryovers = carryoverRepo.findUsableForYear(
        trip.vesselCode(), entry.getKey(), year);
